-- Catálogo de servicios veterinarios administrables desde el sistema (/sistema/servicios).
-- Incluye 24 servicios clínicos, quirúrgicos, diagnósticos y estéticos de Puppy and Kitty.

CREATE TABLE IF NOT EXISTS servicios (
  id             INTEGER       PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  codigo         TEXT          NOT NULL UNIQUE,
  nombre         TEXT          NOT NULL,
  categoria      TEXT          NOT NULL,
  icono          TEXT          NOT NULL DEFAULT '🩺',
  descripcion    TEXT          NOT NULL,
  especies       TEXT          NOT NULL DEFAULT 'Perros y gatos',
  duracion_min   INTEGER       NOT NULL DEFAULT 30 CHECK (duracion_min > 0),
  precio         NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (precio >= 0),
  activo         BOOLEAN       NOT NULL DEFAULT true,
  creado_en      TIMESTAMPTZ   NOT NULL DEFAULT now(),
  actualizado_en TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_servicios_categoria ON servicios(categoria);

ON CONFLICT (codigo) DO NOTHING;
