INSERT INTO servicios (codigo, nombre, categoria, icono, descripcion, especies, duracion_min, precio, activo) VALUES
  ('SRV-001', 'Consulta médica general', 'Consultas y Prevención', '🩺', 'Revisión física integral de signos vitales, peso, temperatura, auscultación cardiopulmonar, diagnóstico clínico y receta médica.', 'Perros, gatos y pequeñas especies', 30, 350.00, true),
  ('SRV-002', 'Consulta de especialidad', 'Especialidades y Urgencias', '👨‍⚕️', 'Valoración avanzada en dermatología, oftalmología, neurología u ortopedia por médico veterinario especialista.', 'Perros y gatos', 45, 650.00, true),
  ('SRV-003', 'Atención de urgencias médicas 24/7', 'Especialidades y Urgencias', '🚨', 'Estabilización inmediata para pacientes en estado crítico, traumatismos, intoxicaciones, dificultad respiratoria o partos distócicos.', 'Perros, gatos y pequeñas especies', 60, 800.00, true),
  ('SRV-004', 'Vacunación séxtuple canina', 'Consultas y Prevención', '💉', 'Inmunización contra moquillo, parvovirus, hepatitis infecciosa, parainfluenza, leptospirosis y coronavirus canino con registro en carnet.', 'Perros', 20, 420.00, true),
  ('SRV-005', 'Vacunación triple felina', 'Consultas y Prevención', '🐱', 'Protección esencial contra panleucopenia felina, rinotraqueítis viral y calicivirus, incluye revisión general previa.', 'Gatos', 20, 400.00, true),
  ('SRV-006', 'Vacunación antirrábica y refuerzos', 'Consultas y Prevención', '🛡️', 'Aplicación de vacuna antirrábica oficial y refuerzos de Bordetella o Giardia con expedición de certificado de vacunación.', 'Perros y gatos', 20, 280.00, true),
  ('SRV-007', 'Desparasitación interna y externa', 'Consultas y Prevención', '💊', 'Tratamiento antiparasitario de amplio espectro contra parásitos gastrointestinales, pulgas, garrapatas y ácaros según el peso.', 'Perros, gatos y pequeñas especies', 20, 320.00, true),
  ('SRV-008', 'Esterilización quirúrgica (OVH / Orquiectomía)', 'Cirugía y Hospitalización', '🏥', 'Cirugía preventiva bajo anestesia inhalatoria con monitoreo multiparamétrico, analgesia postoperatoria y retiro de puntos incluido.', 'Perros y gatos', 90, 1850.00, true),
  ('SRV-009', 'Cirugía de tejidos blandos', 'Cirugía y Hospitalización', '🧤', 'Intervenciones quirúrgicas abdominales, extracción de cuerpos extraños, hernias, tumores cutáneos o mastectomías en quirófano estéril.', 'Perros y gatos', 120, 3500.00, true),
  ('SRV-010', 'Cirugía ortopédica y traumatología', 'Cirugía y Hospitalización', '🦴', 'Reparación de fracturas, luxación patelar y ruptura de ligamento cruzado craneal mediante fijación especializada.', 'Perros y gatos', 150, 5200.00, true),
  ('SRV-011', 'Profilaxis dental por ultrasonido', 'Estética e Higiene', '🦷', 'Eliminación de sarro dental supragingival y subgingival con cavitron ultrasónico, pulido dental y revisión periodontal bajo sedación segura.', 'Perros y gatos', 60, 1200.00, true),
  ('SRV-012', 'Biometría hemática y química sanguínea', 'Diagnóstico y Laboratorio', '🔬', 'Análisis hematológico y perfil bioquímico completo para evaluar función renal, hepática, glucosa y proteínas con resultados el mismo día.', 'Perros y gatos', 30, 750.00, true),
  ('SRV-013', 'Urianálisis y examen coproparasitoscópico', 'Diagnóstico y Laboratorio', '🧪', 'Estudio microscópico y fisicoquímico para detección temprana de infecciones urinarias, cristales y parásitos intestinales.', 'Perros, gatos y pequeñas especies', 30, 450.00, true),
  ('SRV-014', 'Pruebas rápidas de enfermedades infecciosas', 'Diagnóstico y Laboratorio', '📋', 'Diagnóstico rápido en consultorio para Parvovirus, Moquillo, Leucemia/SIDA felino (FeLV/FIV), Ehrlichia y Dirofilaria.', 'Perros y gatos', 25, 580.00, true),
  ('SRV-015', 'Radiología digital veterinaria (Rayos X)', 'Diagnóstico y Laboratorio', '🩻', 'Estudio radiográfico digital de alta definición (2 proyecciones) para evaluación ósea, torácica o abdominal con entrega digital.', 'Perros, gatos y pequeñas especies', 30, 850.00, true),
  ('SRV-016', 'Ultrasonido abdominal y gestacional', 'Diagnóstico y Laboratorio', '🖥️', 'Evaluación ecográfica en tiempo real de órganos internos o diagnóstico y seguimiento de gestación con conteo y viabilidad fetal.', 'Perros y gatos', 40, 950.00, true),
  ('SRV-017', 'Electrocardiograma y valoración cardiológica', 'Especialidades y Urgencias', '❤️', 'Estudio del ritmo cardíaco, presión arterial y valoración prequirúrgica para pacientes geriátricos o con soplo cardíaco.', 'Perros y gatos', 45, 900.00, true),
  ('SRV-018', 'Hospitalización e internamiento 24 horas', 'Cirugía y Hospitalización', '🛏️', 'Internamiento en área climatizada independiente para perros y gatos, con terapia de fluidos intravenosa, medicación y monitoreo continuo.', 'Perros y gatos', 1440, 1100.00, true),
  ('SRV-019', 'Baño higiénico y dermatológico', 'Estética e Higiene', '🛁', 'Baño con agua tibia, shampoo hipoalergénico o medicado, secado profesional, limpieza de oídos, corte de uñas y glándulas anales.', 'Perros y gatos', 60, 380.00, true),
  ('SRV-020', 'Estética canina y felina completa', 'Estética e Higiene', '✂️', 'Servicio integral de peluquería según estándar de raza o corte higiénico a tijera, deslanado, baño completo, hidratación y loción.', 'Perros y gatos', 90, 520.00, true),
  ('SRV-021', 'Implantación de microchip de identificación', 'Consultas y Prevención', '📡', 'Colocación subcutánea de microchip estándar ISO de 15 dígitos con registro de datos del propietario y certificado oficial.', 'Perros y gatos', 20, 680.00, true),
  ('SRV-022', 'Certificado médico de salud y viaje', 'Consultas y Prevención', '✈️', 'Examen físico completo y expedición de certificado médico veterinario oficial para transporte aéreo o terrestre nacional e internacional.', 'Perros y gatos', 30, 550.00, true),
  ('SRV-023', 'Fisioterapia y rehabilitación veterinaria', 'Especialidades y Urgencias', '🐾', 'Sesiones de láser terapéutico, electroestimulación, termoterapia y ejercicios asistidos para recuperación postquirúrgica o artrosis.', 'Perros y gatos', 45, 600.00, true),
  ('SRV-024', 'Consulta geriátrica y control nutricional', 'Consultas y Prevención', '⚖️', 'Chequeo integral para mascotas senior o con sobrepeso, plan de alimentación personalizado y manejo preventivo articular y metabólico.', 'Perros y gatos', 40, 500.00, true)
